package com.example.customer.service;
//Autogenerated code for Service: CustomerService

import com.example.customer.domain.*;
import com.example.customer.payload.*;
import com.example.customer.exception.*;

import com.example.customer.repository.CustomerRepository;


import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import jakarta.transaction.Transactional;

@Service
@Slf4j
@RequiredArgsConstructor
public class CustomerService {
    
   private final CustomerRepository customerRepository;
    
    @Transactional
    public Customer registerACustomer(String email, String name){
    // Activity: registerACustomer      
    // InitialNode: InitialNode1
    // CallOperationAction: Check Customer Existence By Email 
    Boolean customerExists = customerRepository.existsByEmail(email);
    
    // ConditionalNode: CheckDuplicateCustomer
    if (customerExists) {
        // RaiseExceptionAction: DuplicateCustomer
        throw new DuplicateCustomer();
    } 
    else {
          // Declaration: Declare a new customer 
          Customer newCustomer = new Customer();
           newCustomer = new Customer(email, name);
           
          
          // CallOperationAction: Persist Customer 
           newCustomer = customerRepository.save(newCustomer);
          
          return newCustomer;
      }
    
   };
 
    @Transactional
    public Customer updateCustomerDetails(Integer customerId, String newEmail, String newName){
    // Activity: updateCustomerDetails      
    // InitialNode: Init
    // CallOperationAction: Find customer 
    Customer targetCustomer = customerRepository.findByCustomerId(customerId);
    
    // ConditionalNode: Verify Customer
    if (targetCustomer != null) {
        // ConditionalNode: Assign name if not null
        if (newName != null) {
            // Assignment: targetCustomer.name = newName
            targetCustomer.setName(newName);
            
        } 
        
        // ConditionalNode: Assign email if not null
        if (newEmail != null) {
            // Assignment: targetCustomer.email = newEmail
            targetCustomer.setEmail(newEmail);
            
        } 
        
        // CallOperationAction: Update Customer Name and Email 
        Customer updatedCustomer = customerRepository.save(targetCustomer);
        
        return updatedCustomer;
    } 
    else {
          // RaiseExceptionAction: UnknownCustomer
          throw new UnknownCustomer();
      }
    
   };
 
    @Transactional
    public Boolean existsByCustomerId(Integer customerId){
    // Activity: existsByCustomerIdDomainService      
    // InitialNode: existsByCustomerIdDomainService-InitNode
    // CallOperationAction: existsByCustomerId 
    Boolean result = customerRepository.existsByCustomerId(customerId);
    
    return result;
   };
 
}
